report={'file_checks':{},'failures':[], 'checked_monotonic':time.monotonic()}
for name,want in expected.items():
 try:
  with open(name,'rb') as f: actual=hashlib.file_digest(f,'sha256').hexdigest()
  report['file_checks'][name]={'sha256':actual,'matches':actual==want}
  if actual!=want: report['failures'].append(name)
 except OSError as error:
  report['failures'].append(name);report['file_checks'][name]={'error':str(error)}
report['root_mount']=[line for line in Path('/proc/mounts').read_text().splitlines() if line.split()[1]=='/']
report['root_sysfs_path']=str((Path('/sys/class/block') / Path(report['root_mount'][0].split()[0]).name).resolve())
report['touch_recovery_attribute_present']=Path('/sys/bus/spi/devices/spi0.0/recover').exists()
report['package_count']=sum(1 for line in Path('/lib/apk/db/installed').read_text().splitlines() if line.startswith('P:'))
report['all_expected_files_match']=not report['failures']
report['internal_root_confirmed']=len(report['root_mount'])==1 and 'c8000600.mmc' in report['root_sysfs_path']
Path('/tmp/internal-image-files.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:v for k,v in report.items() if k!='file_checks'},indent=2),flush=True)
raise SystemExit(0 if report['all_expected_files_match'] and report['internal_root_confirmed'] and report['touch_recovery_attribute_present'] and report['package_count']==770 else 1)
